(function(){
'use strict';
const Engine=window.MiyarManpower;if(!Engine)return;
const KEY='miyar-manpower-plans-v1';
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function ar(){return document.documentElement.lang!=='en';}function t(a,b){return ar()?a:b;}function fmt(n,d=1){return Number(n).toLocaleString(ar()?'ar-SA':'en-GB',{maximumFractionDigits:d});}
function readPlans(){try{const v=JSON.parse(localStorage.getItem(KEY)||'[]');return Array.isArray(v)?v.slice(0,30):[];}catch{return [];}}
function savePlan(p){const rows=readPlans(),id='MP-'+Date.now().toString(36).toUpperCase(),row={id,...p};localStorage.setItem(KEY,JSON.stringify([row,...rows].slice(0,30)));return row;}
function input(id,label,value='',attrs=''){return '<label class="mp-field">'+label+'<input id="mp-'+id+'" value="'+esc(value)+'" '+attrs+'></label>';}
function currentInstitution(){return window.MiyarInstitutionProfile?.read?.()||null;}
function formValues(){return {strategyObjective:document.getElementById('mp-strategy').value,role:document.getElementById('mp-role').value,department:document.getElementById('mp-department').value,jobFamily:document.getElementById('mp-family').value,workloadUnit:document.getElementById('mp-unit').value,baselineWorkload:document.getElementById('mp-baseline').value,targetWorkload:document.getElementById('mp-target').value,capacityPerFte:document.getElementById('mp-capacity').value,currentFte:document.getElementById('mp-current').value,horizonYears:document.getElementById('mp-horizon').value,attritionPercent:document.getElementById('mp-attrition').value,committedHires:document.getElementById('mp-hires').value,internalSupply:document.getElementById('mp-internal').value,productivityGainPercent:document.getElementById('mp-productivity').value,annualCostPerFte:document.getElementById('mp-cost').value};}
function fill(e){for(const [k,v] of Object.entries({strategy:e.strategyObjective,role:e.role,department:e.department,family:e.jobFamily,unit:e.workloadUnit,baseline:e.baselineWorkload,target:e.targetWorkload,capacity:e.capacityPerFte,current:e.currentFte,horizon:e.horizonYears,attrition:e.attritionPercent,hires:e.committedHires,internal:e.internalSupply,productivity:e.productivityGainPercent,cost:e.annualCostPerFte})){const el=document.getElementById('mp-'+k);if(el)el.value=v??'';}}
function scenarioCard(s){const gap=s.final.gapFte,cls=gap>.5?'warn':gap<-.5?'surplus':'good';return '<article class="mp-scenario '+cls+'"><span>'+esc(ar()?s.labelAr:s.labelEn)+'</span><strong>'+fmt(s.final.requiredFte)+' FTE</strong><small>'+t('المطلوب في نهاية الأفق','Required at horizon')+'</small><div><b>'+fmt(s.final.forecastSupplyFte)+'</b><span>'+t('العرض المتوقع','Forecast supply')+'</span></div><div><b>'+((gap>0?'+':'')+fmt(gap))+'</b><span>'+t('فجوة FTE','FTE gap')+'</span></div></article>';}
function baseTable(plan){const rows=plan.scenarios.base.years;return '<div class="mp-table-wrap"><table><thead><tr>'+[t('السنة','Year'),t('الطلب','Demand'),t('القدرة/FTE','Capacity/FTE'),t('FTE المطلوب','Required FTE'),t('العرض المتوقع','Forecast supply'),t('الفجوة','Gap'),t('عدد مقترح','Suggested headcount')].map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr><td>'+r.year+'</td><td>'+fmt(r.demand)+'</td><td>'+fmt(r.capacityPerFte)+'</td><td>'+fmt(r.requiredFte)+'</td><td>'+fmt(r.forecastSupplyFte)+'</td><td>'+((r.gapFte>0?'+':'')+fmt(r.gapFte))+'</td><td>'+r.recommendedHeadcount+'</td></tr>').join('')+'</tbody></table></div>';}
function results(plan){const base=plan.scenarios.base,high=plan.scenarios.high,low=plan.scenarios.low,cost=base.final.annualGapCost;return '<section class="mp-results"><div class="mp-result-head"><div><span>SCENARIO ESTIMATE</span><h2>'+esc(plan.input.role||plan.input.jobFamily||t('خطة القوى العاملة','Workforce plan'))+'</h2><p>'+esc(plan.input.strategyObjective||t('خطة مبنية على مدخلات الطلب والقدرة.','Plan based on demand and capacity inputs.'))+'</p></div><span class="mp-horizon">'+plan.input.horizonYears+' '+t('سنوات','years')+'</span></div><div class="mp-scenarios">'+scenarioCard(low)+scenarioCard(base)+scenarioCard(high)+'</div><div class="mp-assumptions"><div><b>'+fmt(base.assumptions.annualDemandGrowthPercent)+'%</b><span>'+t('نمو الطلب السنوي · Base','Annual demand growth · Base')+'</span></div><div><b>'+fmt(base.assumptions.cumulativeProductivityPercent)+'%</b><span>'+t('تحسن الإنتاجية التراكمي','Cumulative productivity gain')+'</span></div><div><b>'+fmt(base.assumptions.annualAttritionPercent)+'%</b><span>'+t('الاستنزاف السنوي','Annual attrition')+'</span></div><div><b>'+(cost===null?'—':fmt(cost,0)+' SAR')+'</b><span>'+t('تكلفة الفجوة السنوية عند الأفق','Annual gap cost at horizon')+'</span></div></div><h3>'+t('المسار السنوي — السيناريو الأساسي','Annual path — base scenario')+'</h3>'+baseTable(plan)+'<div class="mp-actions"><h3>'+t('الإجراءات المقترحة للمراجعة','Actions for review')+'</h3>'+plan.actions.map(a=>'<div><strong>'+esc(a.type.toUpperCase())+(a.quantity?' · '+a.quantity:'')+'</strong><p>'+esc(ar()?a.textAr:a.textEn)+'</p></div>').join('')+'</div><div class="mp-uncertainty"><strong>'+t('المجهول يبقى ظاهرًا','Uncertainty stays visible')+'</strong><p>'+esc(t('النتيجة تقدير سيناريو، وليست اعتماد عدد. يجب مراجعة الطلب، القدرة، الاستنزاف، توقيت التوظيف، الإنتاجية والميزانية مع الأعمال والمالية قبل القرار.','This is a scenario estimate, not an approved headcount. Demand, capacity, attrition, hiring timing, productivity and budget must be reviewed with the business and Finance before a decision.'))+'</p></div><div class="action-row"><button class="button button-primary" type="button" data-mp-save>'+t('حفظ الخطة','Save plan')+'</button>'+(base.final.gapFte>.5?'<button class="button button-outline" type="button" data-mp-od>'+t('تحويل الفجوة إلى طلب OD','Send gap to OD')+'</button>':'')+'<button class="button button-outline" type="button" data-mp-export>'+t('تصدير JSON','Export JSON')+'</button></div><p data-mp-status role="status"></p></section>';}
function download(plan){const url=URL.createObjectURL(new Blob([JSON.stringify(plan,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='miyar-manpower-plan.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),500);}
function handoff(plan){const b=plan.scenarios.base.final,gap=Math.max(1,Math.ceil(b.gapFte));sessionStorage.setItem('miyar-manpower-handoff',JSON.stringify({strategyObjective:plan.input.strategyObjective,role:plan.input.role,department:plan.input.department,jobFamily:plan.input.jobFamily,headcount:gap,constraints:'Manpower planning evidence: horizon '+plan.input.horizonYears+' years; base required '+b.requiredFte+' FTE; forecast supply '+b.forecastSupplyFte+' FTE; gap '+b.gapFte+' FTE. Validate responsibilities and job design before approval.'}));location.hash='#enterprise/create';window.dispatchEvent(new Event('hashchange'));}
function bindResults(plan){const root=document.querySelector('.mp-results');root.querySelector('[data-mp-save]').onclick=()=>{const r=savePlan(plan);root.querySelector('[data-mp-status]').textContent=t('حُفظت الخطة محليًا: ','Plan saved locally: ')+r.id;};root.querySelector('[data-mp-export]').onclick=()=>download(plan);const od=root.querySelector('[data-mp-od]');if(od)od.onclick=()=>handoff(plan);}
function render(){if(location.hash!=='#enterprise/manpower')return;const content=document.getElementById('ent-content');if(!content)return;const p=currentInstitution(),profileNote=p?.version?t('يستخدم الإصدار المؤسسي v','Using institution profile v')+p.version:t('لم يُعتمد إعداد مؤسسي بعد؛ ستبقى الإدارة والعائلة نصوصًا يراجعها المستخدم.','No institution profile configured yet; department and family remain user-reviewed text.');document.getElementById('enterprise-heading').textContent=t('تخطيط القوى العاملة','Manpower planning');const bc=document.getElementById('breadcrumb-title');if(bc)bc.textContent=t('تخطيط القوى العاملة','Manpower planning');document.querySelectorAll('.nav-link').forEach(x=>x.classList.remove('active'));document.querySelector('[data-manpower-nav]')?.classList.add('active');content.innerHTML='<section class="mp-page"><div class="mp-heading"><div><span>PHASE 2 · MANPOWER PLANNING</span><h2>'+t('من الطلب الاستراتيجي إلى فجوة قوى عاملة قابلة للفحص','From strategic demand to an inspectable workforce gap')+'</h2><p>'+t('لا يتنبأ معيار بعدد سحري. أنت تدخل الطلب والقدرة والعرض والافتراضات؛ المحرك يعرض الحساب والسيناريوهات والمجهول.','Miyar does not invent a magic headcount. You provide demand, capacity, supply and assumptions; the engine exposes the calculation, scenarios and uncertainty.')+'</p></div><button type="button" class="button button-outline" data-mp-example>'+t('تحميل مثال HC','Load HC example')+'</button></div><div class="mp-profile-note">'+esc(profileNote)+'</div><div class="mp-form"><div class="mp-wide"><label class="mp-field">'+t('الهدف الاستراتيجي','Strategic objective')+'<textarea id="mp-strategy" rows="3"></textarea></label></div>'+input('role',t('الدور / المنصب المرجعي','Role / reference position'))+input('department',t('الإدارة','Department'))+input('family',t('العائلة الوظيفية','Job family'))+input('unit',t('وحدة قياس عبء العمل','Workload unit'),'workload units')+input('baseline',t('عبء العمل الحالي','Current workload'),'100','type="number" min="0.01" step="any"')+input('target',t('عبء العمل المستهدف عند نهاية الأفق','Target workload at horizon'),'130','type="number" min="0.01" step="any"')+input('capacity',t('قدرة FTE واحدة حاليًا','Current capacity per FTE'),'50','type="number" min="0.01" step="any"')+input('current',t('FTE الحالي','Current FTE'),'2','type="number" min="0" step="0.1"')+input('horizon',t('الأفق بالسنوات','Horizon years'),'3','type="number" min="1" max="10" step="1"')+input('attrition',t('الاستنزاف السنوي %','Annual attrition %'),'5','type="number" min="0" max="50" step="0.1"')+input('hires',t('توظيفات معتمدة خلال الأفق','Committed hires over horizon'),'0','type="number" min="0" step="0.1"')+input('internal',t('نقل/تطوير داخلي سيضيف FTE','Internal moves/upskilling adding FTE'),'0','type="number" min="0" step="0.1"')+input('productivity',t('تحسن إنتاجية تراكمي %','Cumulative productivity gain %'),'10','type="number" min="-50" max="200" step="0.1"')+input('cost',t('التكلفة السنوية لكل FTE — اختياري','Annual cost per FTE — optional'),'','type="number" min="0" step="1"')+'</div><div class="mp-run"><button type="button" class="button button-primary" data-mp-run>'+t('احسب الفجوة والسيناريوهات','Calculate gap & scenarios')+'</button><span data-mp-message role="status">'+t('كل الأرقام افتراضات قابلة للتعديل حتى يتم اعتماد بيانات المؤسسة.','All figures remain editable assumptions until organization data is approved.')+'</span></div><div data-mp-results></div></section>';content.querySelector('[data-mp-example]').onclick=()=>fill(Engine.example);content.querySelector('[data-mp-run]').onclick=()=>{try{const plan=Engine.plan(formValues());content.querySelector('[data-mp-results]').innerHTML=results(plan);bindResults(plan);}catch(e){content.querySelector('[data-mp-message]').textContent=e.message;}};}
function ensureNav(){const nav=document.querySelector('.sidebar nav.nav-list');if(!nav)return;let link=nav.querySelector('[data-manpower-nav]');if(!link){link=document.createElement('a');link.href='#enterprise/manpower';link.className='nav-link';link.dataset.manpowerNav='true';link.innerHTML='<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 20h16M7 16v-5m5 5V5m5 11V8"/></svg><span>'+t('تخطيط القوى العاملة','Manpower planning')+'</span>';const create=nav.querySelector('[data-enterprise-open="create"]');create?.after(link);}else link.querySelector('span').textContent=t('تخطيط القوى العاملة','Manpower planning');}
function consumeHandoff(){if(location.hash!=='#enterprise/create')return;let value;try{value=JSON.parse(sessionStorage.getItem('miyar-manpower-handoff')||'null');}catch{}if(!value)return;const panel=document.getElementById('miyar-od-workbench');if(!panel)return;sessionStorage.removeItem('miyar-manpower-handoff');const set=(sel,v)=>{const e=panel.querySelector(sel);if(e){e.value=v||'';e.dispatchEvent(new Event('input',{bubbles:true}));}};set('[data-od-strategy]',value.strategyObjective);set('[data-od-department]',value.department);set('[data-od-constraints]',value.constraints);const h=document.querySelector('[data-number="headcount"]');if(h){h.value=value.headcount;h.dispatchEvent(new Event('input',{bubbles:true}));}const status=panel.querySelector('[data-od-status]');if(status)status.textContent=t('تم استيراد فجوة القوى العاملة. أضف المسؤوليات الفعلية ثم ولّد/راجع حزمة OD.','Workforce gap imported. Add actual responsibilities, then generate/review the OD package.');panel.scrollIntoView({block:'start'});}
window.addEventListener('hashchange',()=>setTimeout(()=>{ensureNav();render();consumeHandoff();},0));window.addEventListener('miyar:navigate',()=>setTimeout(()=>{ensureNav();render();consumeHandoff();},0));document.addEventListener('click',e=>{const link=e.target.closest('[data-manpower-nav]');if(link){e.preventDefault();location.hash='#enterprise/manpower';setTimeout(render,0);}});setTimeout(()=>{ensureNav();render();consumeHandoff();},0);
window.MiyarManpowerWorkbench={render,readPlans,KEY};
})();
